// Una fila por instancia: es lo que convierte «un cron» en «N ejecuciones» (ADR-050).
// El loop vive acá y NO adentro del motor, que es la decisión entera de ese ADR: tres tenants en
// serie dentro del mismo Code node chocan con los 900 s del watchdog y matan la corrida de todos.
const r = $input.first().json || {};
const instancias = r.instancias || [];

// Lista vacía es un estado legítimo (nadie contrató el pipeline, o se pausaron todas), no un
// error: se sale sin disparar y sin ensuciar el log de fallos.
if (!instancias.length) {
  console.log('[Dispatcher] 0 instancias activas de ' + (r.workflow || '?') + ': no hay nada que disparar');
  return [];
}

console.log('[Dispatcher] ' + instancias.length + ' instancia(s) de ' + r.workflow + ' → ' + $('Config').first().json.destino + ': ' + instancias.map(i => i.cliente + '/' + i.slug).join(', '));
return instancias.map(i => ({ json: { instancia: i.id, cliente: i.cliente, slug: i.slug } }));

// El dispatcher no sabe qué pasó adentro de las corridas que disparó, y no tiene que saberlo
// (ADR-050: no tiene estado y no registra nada — el registro es `runs`, y lo escribe cada motor).
// Esto es solo para que la ejecución del dispatcher se lea de un vistazo en n8n.
const items = $input.all();
const fallados = items.filter(i => i.json && i.json.error);
console.log('[Dispatcher] disparadas ' + (items.length - fallados.length) + '/' + items.length + ' instancias');
if (fallados.length) console.log('[Dispatcher] ⚠️ ' + fallados.length + ' no recibieron la señal; sus otros triggers siguen vivos (el botón ▶ del cockpit)');
return [{ json: { disparadas: items.length - fallados.length, fallidas: fallados.length } }];
